29:#[inline(always)]
30:pub(super) fn measured_call<T>(call: impl FnOnce() -> T) -> MeasuredCall<T> {
31:    let start_tsc = rdtscp().0;
32:    let value = call();
33:    let end_tsc = rdtscp().0;
34:
35:    MeasuredCall {
36:        value,
37:        start_tsc,
38:        end_tsc,
39:    }
40:}
