42:pub(super) fn dsa_operation_payload_size(operation: DsaOperationClass) -> usize {
43:    operation.default_payload_size()
44:}
45:
46:pub(super) fn traffic_class_operation_size(traffic_class: TrafficClass) -> Option<usize> {
47:    match traffic_class {
48:        TrafficClass::SubmitOnly => None,
49:        TrafficClass::NoopCompletion => Some(0),
50:        TrafficClass::Memmove64 => Some(64),
51:        TrafficClass::Memmove4k => Some(4096),
52:    }
53:}
54:
55:pub(super) struct OperationSlots {
56:    pub(super) descriptors: Vec<DsaHwDesc>,
57:    pub(super) completions: Vec<DsaCompletionRecord>,
58:    pub(super) sources: Vec<u8>,
59:    pub(super) destinations: Vec<u8>,
60:}
61:
62:impl OperationSlots {
63:    pub(super) fn new(count: usize, operation: DsaOperationClass) -> Self {
64:        Self::new_with_payload(count, operation, operation.default_payload_size())
65:    }
66:
67:    pub(super) fn new_with_payload(
68:        count: usize,
69:        operation: DsaOperationClass,
70:        payload_size: usize,
71:    ) -> Self {
72:        let mut descriptors = vec![DsaHwDesc::default(); count];
73:        let mut completions = vec![DsaCompletionRecord::default(); count];
74:
75:        let mut sources = vec![0xa5; count * payload_size];
76:        let mut destinations = vec![0; count * payload_size];
77:
78:        touch_pages(&mut sources);
79:        touch_pages(&mut destinations);
80:
81:        for slot in 0..count {
82:            fill_descriptor(
83:                &mut descriptors[slot],
84:                &mut completions[slot],
85:                &mut sources,
86:                &mut destinations,
87:                slot,
88:                payload_size,
89:                operation,
90:            );
91:        }
92:
93:        Self {
94:            descriptors,
95:            completions,
96:            sources,
97:            destinations,
98:        }
99:    }
100:}
101:
102:fn touch_pages(buf: &mut [u8]) {
103:    for offset in (0..buf.len()).step_by(4096) {
104:        touch_byte(buf, offset);
105:    }
106:
107:    if !buf.is_empty() {
108:        touch_byte(buf, buf.len() - 1);
109:    }
110:}
111:
112:fn touch_byte(buf: &mut [u8], offset: usize) {
113:    // SAFETY: callers pass offsets inside `buf`, so the pointer is in-bounds for
114:    // a one-byte volatile read/write. The read-then-write keeps the byte value
115:    // unchanged while forcing the backing page to be faulted in before DSA, which
116:    // cannot service ordinary CPU page faults for us.
117:    unsafe {
118:        let ptr = buf.as_mut_ptr().add(offset);
119:        let value = ptr.read_volatile();
120:        ptr.write_volatile(value);
121:    }
122:}
123:
124:pub(super) fn fill_descriptor(
125:    desc: &mut DsaHwDesc,
126:    completion: &mut DsaCompletionRecord,
127:    sources: &mut [u8],
128:    destinations: &mut [u8],
129:    slot: usize,
130:    payload_size: usize,
131:    operation: DsaOperationClass,
132:) {
